import{_ as i,c as o,o as e,a0 as t}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Guida rapida al gioco mentale","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/it/summary-sheet.md","filePath":"public/downloads/it/summary-sheet.md"}');const r=i({name:"public/downloads/it/summary-sheet.md"},[["render",function(i,a,r,n,l,s){return e(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="guida-rapida-al-gioco-mentale" tabindex="-1">Guida rapida al gioco mentale <a class="header-anchor" href="#guida-rapida-al-gioco-mentale" aria-label="Permalink to &quot;Guida rapida al gioco mentale&quot;">​</a></h1><p><strong>Accademia di bocce - Riepilogo di una pagina</strong></p><hr><h2 id="lo-stato-di-zona-flusso" tabindex="-1">Lo stato di zona/flusso <a class="header-anchor" href="#lo-stato-di-zona-flusso" aria-label="Permalink to &quot;Lo stato di zona/flusso&quot;">​</a></h2><p><strong>Due modalità mentali:</strong></p><table tabindex="0"><thead><tr><th>Modalità di pianificazione</th><th>Modalità di esecuzione</th></tr></thead><tbody><tr><td>Analizza il terreno</td><td>Fidati del tuo corpo</td></tr><tr><td>Scegli la strategia</td><td>Non pensare</td></tr><tr><td>Valutare i rischi</td><td>Momento presente</td></tr><tr><td>Prendere decisioni</td><td>Esecuzione automatica</td></tr></tbody></table><p><strong>The Switch:</strong> Pianifica prima, fluisci durante</p><hr><h2 id="critico-interiore-vs-coach-interiore" tabindex="-1">Critico interiore vs. Coach interiore <a class="header-anchor" href="#critico-interiore-vs-coach-interiore" aria-label="Permalink to &quot;Critico interiore vs. Coach interiore&quot;">​</a></h2><p>| Critico Interiore ❌ | Coach Interiore ✅ | ||--------------------------------| | &quot;È stato terribile!&quot; | &quot;Cosa posso imparare?&quot; | | &quot;Fai sempre degli errori&quot; | &quot;Prossimo colpo, nuovo inizio&quot; | | &quot;Tutti ti guardano fallire&quot; | &quot;L&#39;ho già fatto prima&quot; | | &quot;Non sei abbastanza bravo&quot; | &quot;Fidati del processo&quot; |</p><p><strong>Reinquadra:</strong> Pausa → Reinquadra → Reimposta → Rimetti a fuoco</p><hr><h2 id="_3-reset-del-respiro" tabindex="-1">3-Reset del respiro <a class="header-anchor" href="#_3-reset-del-respiro" aria-label="Permalink to &quot;3-Reset del respiro&quot;">​</a></h2><p><strong>Usare dopo errori o pressioni:</strong></p><ol><li><strong>Respiro 1:</strong> Nota la tensione (dove?)</li><li><strong>Respiro 2:</strong> Rilascia la tensione (lascia andare)</li><li><strong>Respiro 3:</strong> Rimetti a fuoco (questo scatto, ora)</li></ol><hr><h2 id="routine-pre-tiro" tabindex="-1">Routine pre-tiro <a class="header-anchor" href="#routine-pre-tiro" aria-label="Permalink to &quot;Routine pre-tiro&quot;">​</a></h2><p><strong>Stessa routine, ogni tiro:</strong></p><ol><li><strong>Visualizza</strong> - Guarda lo scatto</li><li><strong>Respira</strong> - Un respiro profondo</li><li><strong>Ancora</strong> - Tocca la boccia, senti il peso</li><li><strong>Esegui</strong> - Fidati e lancia</li></ol><hr><h2 id="protocollo-di-recupero-degli-errori" tabindex="-1">Protocollo di recupero degli errori <a class="header-anchor" href="#protocollo-di-recupero-degli-errori" aria-label="Permalink to &quot;Protocollo di recupero degli errori&quot;">​</a></h2><p><strong>Dopo un brutto tiro:</strong></p><ol><li><strong>Riconoscimento</strong> - &quot;Non è andato come previsto&quot;</li><li><strong>Rilascio</strong> - Ripristino fisico (scuotilo via)</li><li><strong>Rimetti a fuoco</strong> - &quot;Il prossimo scatto è nuovo&quot;</li><li><strong>Esegui</strong> - Fidati della tua routine</li></ol><hr><h2 id="allenamento-di-questa-settimana" tabindex="-1">Allenamento di questa settimana <a class="header-anchor" href="#allenamento-di-questa-settimana" aria-label="Permalink to &quot;Allenamento di questa settimana&quot;">​</a></h2><p><strong>Scegli UNA tecnica:</strong></p><ul><li>[ ] 3-Reset del respiro dopo ogni errore</li><li>[ ] Routine pre-tiro su ogni lancio</li><li>[ ] Riformula un pensiero del Critico Interiore per sessione</li><li>[ ] Esercitati a cambiare la pianificazione → modalità di esecuzione</li></ul><hr><h2 id="tieni-traccia-dei-tuoi-progressi" tabindex="-1">Tieni traccia dei tuoi progressi <a class="header-anchor" href="#tieni-traccia-dei-tuoi-progressi" aria-label="Permalink to &quot;Tieni traccia dei tuoi progressi&quot;">​</a></h2><p><strong>Avviso:</strong></p><ul><li>Quando ti senti più in flusso?</li><li>Cosa attiva il tuo Critico Interiore?</li><li>Quale tecnica ti è più utile?</li><li>Come cambiano le tue prestazioni?</li></ul><hr><h2 id="principi-chiave" tabindex="-1">Principi chiave <a class="header-anchor" href="#principi-chiave" aria-label="Permalink to &quot;Principi chiave&quot;">​</a></h2><ol><li><strong>Il flusso è accessibile</strong> - Puoi imparare a inserirlo in modo coerente</li><li><strong>La tua voce interiore è importante</strong> - Allenati, non criticare</li><li><strong>Funzionano strumenti semplici</strong>: 3 respiri, una routine, un reset</li><li><strong>La pratica è la chiave</strong> - Le capacità mentali necessitano di allenamento come le capacità tecniche</li></ol><hr><h2 id="risorse" tabindex="-1">Risorse <a class="header-anchor" href="#risorse" aria-label="Permalink to &quot;Risorse&quot;">​</a></h2><p><strong>Continua ad imparare su carreau.app:</strong></p><ul><li>The Zone - Immersione profonda nello stato di flusso</li><li>Forza mentale - Gestione avanzata della pressione</li><li>Modello di obiettivo: struttura il tuo sviluppo</li><li>Modello di diario: tieni traccia dei tuoi progressi</li></ul><hr><p><strong>Ricorda:</strong> L&#39;allenamento mentale non riguarda il pensiero positivo. Si tratta di tecniche pratiche che ti aiutano a ottenere le migliori prestazioni sotto pressione.</p><hr><p><em>Accademia di bocce - Sviluppo dei giocatori d&#39;élite</em><em>carreau.app</em></p>',42)])])}]]);export{a as __pageData,r as default};
